#ifndef INCLUDED_SW_INC_TXTRFMRK_HXX
#define INCLUDED_SW_INC_TXTRFMRK_HXX

#include "txatbase.hxx"

class SwDoc;
class SwWrtShell;
class SwTextNode;

// Attribute for content-/position references in text.
class SwTextRefMark final : public SwTextAttrEnd
{
    SwTextNode * m_pTextNode;
    sal_Int32 * m_pEnd; // end is optional (point reference)

public:
    SwTextRefMark(
        const SfxPoolItemHolder& rAttr,
        sal_Int32 const nStart,
        sal_Int32 const*const pEnd = nullptr);

    ~SwTextRefMark();

    virtual const sal_Int32* GetEnd() const override;       // SwTextAttr
    virtual void SetEnd(sal_Int32) override;       // SwTextAttr
    void UpdateFieldContent(SwDoc* pDoc, SwWrtShell& rWrtSh, const OUString& aContent);

    // get and set TextNode pointer
    inline const SwTextNode& GetTextNode() const;
    void ChgTextNode( SwTextNode* pNew ) { m_pTextNode = pNew; }
    void dumpAsXml(xmlTextWriterPtr pWriter) const override;
};

inline const SwTextNode& SwTextRefMark::GetTextNode() const
{
    assert( m_pTextNode );
    return *m_pTextNode;
}

#endif

